    def pick(cols):
        return next((d for d in datasets if all(c in d.get('columns', []) for c in cols)), None)
    inv = pick(['sku', 'product_name_en', 'stock_on_hand'])
    sold = pick(['sku', 'product_name_en', 'units_sold'])
    po = pick(['month', 'total_amount', 'total_boxes'])
    openpo = pick(['po_number', 'status', 'total_amount', 'eta_date'])
    out = []
    stock = {r['sku']: r for r in (inv['rows'] if inv else [])}
    sales = {r['sku']: r for r in (sold['rows'] if sold else [])}
    alerts = []
    for sku, s in stock.items():
        u = sales.get(sku, {}).get('units_sold')
        if not u:
            continue
        days = round(s['stock_on_hand'] / (u / 30.0), 1)
        alerts.append((s['product_name_en'], sku, s['stock_on_hand'], u, days))
    alerts.sort(key=lambda x: x[4])
    for name, sku, qty, u, days in alerts:
        out.append({'title': '库存可售天数', 'detail': '%s（%s）期末库存 %s 件，月销 %s 件，约可售 %s 天%s' % (name, sku, qty, u, days, '，需立即补货' if days < 15 else ''), 'evidence': {'stock': qty, 'units_sold': u, 'days': days}})
    if po:
        rows = po['rows']
        last = rows[-1]
        prev = rows[-2] if len(rows) > 1 else None
        mom = round((last['total_amount'] - prev['total_amount']) / prev['total_amount'] * 100, 1) if prev else None
        out.append({'title': '采购趋势', 'detail': '%s 采购金额 %s、%s 箱，环比 %s%%' % (last['month'], last['total_amount'], last['total_boxes'], mom), 'evidence': {'month': last['month'], 'amount': last['total_amount'], 'boxes': last['total_boxes'], 'mom_pct': mom}})
    if openpo:
        rows = openpo['rows']
        amt = round(sum(r['total_amount'] for r in rows), 2)
        eta = min(r['eta_date'] for r in rows)
        out.append({'title': '在途采购', 'detail': '%s 张未完成采购单合计 %s，最早预计到货 %s，需跟进付款与到货' % (len(rows), amt, eta), 'evidence': {'open_po': len(rows), 'amount': amt, 'earliest_eta': eta}})
    return out

def analyze(datasets):
    out = []
    pay = next((d for d in datasets if 'payment_terms' in d.get('columns', [])), None)
    ev = next((d for d in datasets if 'received_count' in d.get('columns', [])), None)
    po = next((d for d in datasets if 'po_number' in d.get('columns', []) and 'total_amount' in d.get('columns', [])), None)
    if pay:
        rows = pay['rows']
        amt = {r['po_number']: r['total_amount'] for r in (po['rows'] if po else [])}
        total = sum(amt.get(r['po_number'], 0) for r in rows)
        terms = {}
        for r in rows:
            terms[r['payment_terms']] = terms.get(r['payment_terms'], 0) + 1
        out.append({'title': '7 单待付款采购单合计金额与账期分布', 'detail': '处于 awaiting_payment 的 7 单合计金额约 ' + str(round(total, 2)) + '，账期分布为 ' + '、'.join(k + ' ' + str(v) + ' 单' for k, v in terms.items()) + '，最早提交于 ' + min(r['submitted_at'] for r in rows)[:10] + '，最晚 ' + max(r['submitted_at'] for r in rows)[:10] + '，均早于对应 ETA，存在付款流程滞后风险。', 'evidence': {'order_count': len(rows), 'total_amount': round(total, 2), 'terms': terms}})
    if ev:
        rows = ev['rows']
        no_ev = sum(1 for r in rows if r['event_count'] == 0)
        out.append({'title': 'ETA 已过或临近的采购单无任何收货/索赔事件', 'detail': str(len(rows)) + ' 单中 ' + str(no_ev) + ' 单收货、破损索赔事件记录均为 0，其中 4 单 ETA 为 2026-08-20、3 单为 2026-09-20，到货与验收环节完全缺失记录，存在货损与账实不符风险。', 'evidence': {'po_count': len(rows), 'no_event_count': no_ev}})
    return out
